def survivorship_gap(ret, listed):
    alive = listed.iloc[-1]
    everyone = ret.mean(axis=1).mean() * 252
    survivors = ret.loc[:, alive].mean(axis=1).mean() * 252
    return (round(float(everyone), 4), round(float(survivors), 4))

def delisting_return_kept(ret, listed):
    out = []
    for name in sorted(listed.columns):
        days = listed.index[listed[name]]
        if len(days) and not listed[name].iloc[-1]:
            last = days[-1]
            out.append((name, last.strftime("%Y-%m-%d"), round(float(ret.loc[last, name]), 4)))
    return out
